import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates all addresses styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createAddressesStyles = (t: PdfcnTheme) => {
  const { spacing, fontWeights, typography } = t.primitives;

  return StyleSheet.create({
    addressText: {
      // No flex here — Text nodes with flex shorthand get flexBasis:0, which causes
      // Yoga to under-measure multi-line text height. flex lives on the column View.
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      lineHeight: t.typography.body.lineHeight,
    },
    column: {
      display: "flex",
      flex: 1,
      flexDirection: "column",
    },
    columnGap: {
      width: spacing[8],
    },
    container: {
      display: "flex",
      flexDirection: "row",
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
    label: {
      color: t.colors.primary,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      fontWeight: fontWeights.semibold,
      letterSpacing: 1,
      marginBottom: spacing[1],
    },
  });
};

import type React from "react";

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/components/pdf/theme-provider";
import {
  View,
  Text as PDFText,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";

import { createAddressesStyles } from "./addresses.styles";
import type { AddressesProps } from "./addresses.types";

type Styles = ReturnType<typeof createAddressesStyles>;

const splitLines = (address: string): string[] => address.split(/\r?\n/);

const renderAddressColumn = (
  label: string,
  address: string,
  accent: string,
  styles: Styles,
  columnKey: string,
  columnStyle?: Style
): React.ReactElement => (
  <View key={columnKey} style={columnStyle ? [styles.column, columnStyle] : styles.column}>
    <PDFText style={[styles.label, { color: accent }]}>
      {label.toUpperCase()}
    </PDFText>
    <View>
      {splitLines(address).map((line, index) => (
        <PDFText
          key={
            line ? `${columnKey}-line-${index}-${line}` : `${columnKey}-blank-${index}`
          }
          style={styles.addressText}
        >
          {line}
        </PDFText>
      ))}
    </View>
  </View>
);

export const PdfAddresses = ({
  from,
  to,
  fromLabel = "From",
  toLabel = "Bill to",
  accentColor,
  style,
}: AddressesProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createAddressesStyles(theme), [theme]);
  const accent = accentColor ?? theme.colors.primary;

  const containerStyles: Style[] = [styles.container];
  if (style) {
    containerStyles.push(style);
  }

  return (
    <View style={containerStyles}>
      {renderAddressColumn(fromLabel, from, accent, styles, "from")}
      <View style={styles.columnGap} />
      {renderAddressColumn(toLabel, to, accent, styles, "to")}
    </View>
  );
};

import type { Style } from "@/lib/pdf-primitives";

/**
 * Sender and recipient address blocks side by side ("From" / "Bill to",
 * "Ship from" / "Ship to"). Used by invoice, quote, and packing-slip blocks.
 * Props - `from` | `to` | `fromLabel` | `toLabel` | `accentColor` | `style` | `renderingBase`
 * @see {@link PdfAddresses}
 */
export interface AddressesProps {
  /** Sender address. Multiline strings render as stacked lines. */
  from: string;
  /** Recipient address. Multiline strings render as stacked lines. */
  to: string;
  /**
   * Label above the sender address.
   * @default 'From'
   */
  fromLabel?: string;
  /**
   * Label above the recipient address.
   * @default 'Bill to'
   */
  toLabel?: string;
  /**
   * Color of the labels. Falls back to the theme primary color.
   */
  accentColor?: string;
  style?: Style;
  /**
   * @default 'takumi'
   * Forme rendering ships as a follow-up (shadcn-labs/pdfcn#71).
   */
  renderingBase?: "takumi";
}
